function criarMultiplicador(fator) {
  return function (numero) {
    return numero * fator;
  };
}

const duplicar = criarMultiplicador(2);
const triplicar = criarMultiplicador(3);

console.log(duplicar(5));  // 10
console.log(triplicar(5)); // 15

function aplicarATodos(fn, valores) {
  return valores.map(fn);
}

console.log(aplicarATodos(duplicar, [1, 2, 3])); // [2, 4, 6]

let contador = 0;
function incrementarContadorImpuro() {
  contador += 1;
  return contador;
}

function somar(a, b) {
  return a + b;
}

console.log(somar(2, 3)); // 5
console.log(somar(2, 3)); // 5, sempre o mesmo para os mesmos argumentos

console.log(incrementarContadorImpuro()); // 1
console.log(incrementarContadorImpuro()); // 2, resultado diferente com a mesma "chamada"

const utilizador = { nome: "Marta", idade: 28 };

// Atualização imutável: cria um novo objeto
const utilizadorAtualizado = { ...utilizador, idade: 29 };

console.log(utilizador);           // { nome: "Marta", idade: 28 } - inalterado
console.log(utilizadorAtualizado); // { nome: "Marta", idade: 29 }

const numeros = [1, 2, 3];
const numerosComNovo = [...numeros, 4]; // em vez de numeros.push(4)

console.log(numeros);        // [1, 2, 3]
console.log(numerosComNovo); // [1, 2, 3, 4]

function curry(fn) {
  return function curried(...args) {
    if (args.length >= fn.length) {
      return fn.apply(this, args);
    }
    return (...maisArgs) => curried(...args, ...maisArgs);
  };
}

const somarTres = (a, b, c) => a + b + c;
const somarTresCurried = curry(somarTres);

console.log(somarTresCurried(1)(2)(3)); // 6
console.log(somarTresCurried(1, 2)(3)); // 6
console.log(somarTresCurried(1, 2, 3)); // 6

const removerEspacos = (texto) => texto.trim();
const paraMinusculas = (texto) => texto.toLowerCase();
const paraSlug = (texto) => texto.replace(/\s+/g, "-");

const pipe = (...fns) => (valorInicial) =>
  fns.reduce((valor, fn) => fn(valor), valorInicial);

const compose = (...fns) => (valorInicial) =>
  fns.reduceRight((valor, fn) => fn(valor), valorInicial);

const gerarSlugPipe = pipe(removerEspacos, paraMinusculas, paraSlug);
const gerarSlugCompose = compose(paraSlug, paraMinusculas, removerEspacos);

console.log(gerarSlugPipe("  Programação Funcional em JS  "));
// "programação-funcional-em-js"
console.log(gerarSlugCompose("  Programação Funcional em JS  "));
// "programação-funcional-em-js", mesmo resultado, funções na ordem inversa

// Estilo imperativo
function calcularTotalImperativo(itens) {
  let total = 0;
  for (let i = 0; i < itens.length; i++) {
    if (itens[i].comprado) {
      total += itens[i].preco;
    }
  }
  return total;
}

// Estilo funcional
const calcularTotalFuncional = (itens) =>
  itens
    .filter((item) => item.comprado)
    .reduce((total, item) => total + item.preco, 0);

const itens = [
  { nome: "Livro", preco: 15, comprado: true },
  { nome: "Caneta", preco: 2, comprado: false },
  { nome: "Caderno", preco: 5, comprado: true },
];

console.log(calcularTotalImperativo(itens)); // 20
console.log(calcularTotalFuncional(itens));  // 20

