function aplicarDuasVezes(fn, valor) {
  return fn(fn(valor));
}

const duplicar = (n) => n * 2;
console.log(aplicarDuasVezes(duplicar, 5)); // 20

const paraMaiusculas = (texto) => texto.toUpperCase();
console.log(aplicarDuasVezes(paraMaiusculas, "ola")); // "OLA"

exercises.statement:
A função seguinte é impura porque muta o array recebido:

function adicionarProdutoImpuro(carrinho, produto) {
  carrinho.push(produto);
  return carrinho;
}

Escreva uma versão pura chamada adicionarProduto que receba um array de produtos e um novo produto, e devolva um NOVO array com o produto adicionado, sem alterar o array original. Demonstre com console.log que o array original passado como argumento não é alterado depois de chamar a sua função.

exercises.solution_code:
function adicionarProduto(carrinho, produto) {
  return [...carrinho, produto];
}

const carrinhoOriginal = ["Teclado", "Rato"];
const novoCarrinho = adicionarProduto(carrinhoOriginal, "Monitor");

console.log(carrinhoOriginal); // ["Teclado", "Rato"] - inalterado
console.log(novoCarrinho);     // ["Teclado", "Rato", "Monitor"]

function curry(fn) {
  return function curried(...argsRecebidos) {
    if (argsRecebidos.length >= fn.length) {
      return fn(...argsRecebidos);
    }
    return (...maisArgs) => curried(...argsRecebidos, ...maisArgs);
  };
}

const calcularVolume = (comprimento, largura, altura) => comprimento * largura * altura;
const calcularVolumeCurried = curry(calcularVolume);

const caixaComBaseFixa = calcularVolumeCurried(2, 3);

console.log(caixaComBaseFixa(4));  // 24
console.log(caixaComBaseFixa(10)); // 60

