const aplicarDesconto = (preco) => preco * 0.9;
const aplicarIVA = (preco) => preco * 1.23;
const arredondar = (preco) => Math.round(preco * 100) / 100;

const calcularPrecoFinal = pipe(aplicarDesconto, aplicarIVA, arredondar);

console.log(calcularPrecoFinal(100)); // 110.7

exercises.statement:
Tem o seguinte código imperativo que, dado um array de objetos { nome, idade, ativo }, calcula a soma das idades apenas dos utilizadores ativos:

function somarIdadesAtivosImperativo(utilizadores) {
  let soma = 0;
  for (let i = 0; i < utilizadores.length; i++) {
    if (utilizadores[i].ativo) {
      soma += utilizadores[i].idade;
    }
  }
  return soma;
}

Reescreva a mesma lógica num estilo funcional, somarIdadesAtivosFuncional, compondo funções puras (sem loops explícitos nem variáveis mutáveis), e teste-a com o mesmo array de utilizadores para confirmar que ambas dão o mesmo resultado.

exercises.solution_code:
function somarIdadesAtivosFuncional(utilizadores) {
  return utilizadores
    .filter((utilizador) => utilizador.ativo)
    .map((utilizador) => utilizador.idade)
    .reduce((soma, idade) => soma + idade, 0);
}

const utilizadores = [
  { nome: "Ana", idade: 30, ativo: true },
  { nome: "Bruno", idade: 25, ativo: false },
  { nome: "Carla", idade: 40, ativo: true },
];

console.log(somarIdadesAtivosFuncional(utilizadores)); // 70
